package iface

import (
	"github.com/rmorlok/authproxy/internal/apid"
	"github.com/rmorlok/authproxy/internal/database"
	"github.com/rmorlok/authproxy/internal/schema/common"
	toolschema "github.com/rmorlok/authproxy/internal/schema/resources/tools"
)

// ErrToolManaged means a management write targeted a Tool generated by a
// ToolSet. Generated Tools change only through their owning ToolSet.
var ErrToolManaged = database.ErrToolManaged

// ErrToolRevisionConflict means a write observed a revision that is no longer
// active, usually because a concurrent update or deletion committed first.
var ErrToolRevisionConflict = database.ErrToolRevisionConflict

// Tool is the management view of one connection-bound operation. It carries
// the active revision's decrypted definition so the canonical resource can be
// rendered, and must not be returned through agent-facing discovery, which
// exposes only usage descriptors.
type Tool interface {
	GetId() apid.ID
	GetNamespace() string
	GetName() common.ResourceName
	GetConnectionId() apid.ID

	// GetActiveRevision returns the revision that new invocations would admit.
	GetActiveRevision() uint64

	// GetManagedByToolSetId returns the owning ToolSet for a generated Tool and
	// apid.Nil for a standalone Tool.
	GetManagedByToolSetId() apid.ID

	// GetResource returns a detached canonical resource for API responses.
	GetResource() *toolschema.Tool
}
